import { useState } from "react";
import { PageMeta } from "@/components/PageMeta";
import { AdminLayout } from "@/components/admin/AdminLayout";
import { supabase } from "@/integrations/supabase/client";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from "@/components/ui/alert-dialog";
import { toast } from "@/hooks/use-toast";
import { Loader2, Trash2, Search, Image as ImageIcon, Copy } from "lucide-react";
import { format } from "date-fns";

interface MediaAsset {
  id: string;
  url: string;
  thumbnail_url: string | null;
  type: string;
  alt_text: string | null;
  title: string | null;
  created_at: string;
  metadata: Record<string, unknown> | null;
}

export default function MediaLibraryPage() {
  const queryClient = useQueryClient();
  const [search, setSearch] = useState("");
  const [deleteId, setDeleteId] = useState<string | null>(null);
  const [previewAsset, setPreviewAsset] = useState<MediaAsset | null>(null);

  const { data: assets, isLoading } = useQuery({
    queryKey: ["media_assets", search],
    queryFn: async () => {
      let query = supabase
        .from("media_assets")
        .select("*")
        .order("created_at", { ascending: false });

      if (search.trim()) {
        query = query.or(`title.ilike.%${search}%,alt_text.ilike.%${search}%`);
      }

      const { data, error } = await query;
      if (error) throw error;
      return data as MediaAsset[];
    },
  });

  const deleteMutation = useMutation({
    mutationFn: async (id: string) => {
      const { error } = await supabase.from("media_assets").delete().eq("id", id);
      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["media_assets"] });
      toast({ title: "Asset deleted" });
      setDeleteId(null);
    },
    onError: (err: any) => {
      toast({ title: "Error", description: err.message, variant: "destructive" });
    },
  });

  async function copyUrl(url: string) {
    try {
      await navigator.clipboard.writeText(url);
      toast({ title: "URL copied to clipboard" });
    } catch {
      toast({ title: "Failed to copy", description: "Clipboard access was denied.", variant: "destructive" });
    }
  }

  if (isLoading) {
    return (
      <AdminLayout>
        <div className="flex justify-center py-20">
          <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
        </div>
      </AdminLayout>
    );
  }

  return (
    <>
      <PageMeta title="Media Library | Admin" description="Manage media assets." />
      <AdminLayout>
        <div className="flex items-center justify-between mb-6">
          <h1 className="text-2xl font-bold font-sans">Media Library</h1>
        </div>

        <div className="relative mb-6 max-w-sm">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
          <Input
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Search by title or alt text…"
            className="pl-9"
          />
        </div>

        {!assets?.length ? (
          <div className="text-center py-16 text-muted-foreground">
            <ImageIcon className="h-12 w-12 mx-auto mb-3 opacity-40" />
            <p className="text-lg font-medium">No media assets yet</p>
            <p className="text-sm mt-1">Generate images with AI from the blog editor to populate your library.</p>
          </div>
        ) : (
          <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
            {assets.map((asset) => (
              <div key={asset.id} className="group relative rounded-lg border border-border bg-card overflow-hidden">
                <div
                  className="aspect-video bg-muted cursor-pointer"
                  onClick={() => setPreviewAsset(asset)}
                >
                  <img
                    src={asset.thumbnail_url || asset.url}
                    alt={asset.alt_text || asset.title || "Media"}
                    className="w-full h-full object-cover"
                    loading="lazy"
                  />
                </div>
                <div className="p-2">
                  <p className="text-xs font-medium truncate">{asset.title || "Untitled"}</p>
                  <p className="text-xs text-muted-foreground">{asset.created_at ? format(new Date(asset.created_at), "MMM d, yyyy") : ""}</p>
                </div>
                <div className="absolute top-1 right-1 opacity-0 group-hover:opacity-100 transition-opacity flex gap-1">
                  <Button variant="secondary" size="icon" className="h-7 w-7" onClick={() => copyUrl(asset.url)}>
                    <Copy className="h-3.5 w-3.5" />
                  </Button>
                  <Button variant="destructive" size="icon" className="h-7 w-7" onClick={() => setDeleteId(asset.id)}>
                    <Trash2 className="h-3.5 w-3.5" />
                  </Button>
                </div>
              </div>
            ))}
          </div>
        )}

        {/* Preview Dialog */}
        <Dialog open={!!previewAsset} onOpenChange={(open) => !open && setPreviewAsset(null)}>
          <DialogContent className="max-w-2xl">
            <DialogHeader>
              <DialogTitle>{previewAsset?.title || "Media Preview"}</DialogTitle>
            </DialogHeader>
            {previewAsset && (
              <div className="space-y-3">
                <img src={previewAsset.url} alt={previewAsset.alt_text || ""} className="w-full rounded-md" />
                {previewAsset.alt_text && <p className="text-sm text-muted-foreground"><strong>Alt text:</strong> {previewAsset.alt_text}</p>}
                <div className="flex gap-2">
                  <Button size="sm" variant="outline" onClick={() => copyUrl(previewAsset.url)} className="gap-1">
                    <Copy className="h-3.5 w-3.5" /> Copy URL
                  </Button>
                </div>
              </div>
            )}
            <DialogFooter>
              <Button variant="outline" onClick={() => setPreviewAsset(null)}>Close</Button>
            </DialogFooter>
          </DialogContent>
        </Dialog>

        {/* Delete Confirmation */}
        <AlertDialog open={!!deleteId} onOpenChange={(open) => !open && setDeleteId(null)}>
          <AlertDialogContent>
            <AlertDialogHeader>
              <AlertDialogTitle>Delete this asset?</AlertDialogTitle>
              <AlertDialogDescription>This action cannot be undone.</AlertDialogDescription>
            </AlertDialogHeader>
            <AlertDialogFooter>
              <AlertDialogCancel>Cancel</AlertDialogCancel>
              <AlertDialogAction onClick={() => deleteId && deleteMutation.mutate(deleteId)} className="bg-destructive text-destructive-foreground hover:bg-destructive/90">
                {deleteMutation.isPending ? <Loader2 className="h-4 w-4 animate-spin" /> : "Delete"}
              </AlertDialogAction>
            </AlertDialogFooter>
          </AlertDialogContent>
        </AlertDialog>
      </AdminLayout>
    </>
  );
}

import { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { AdminLayout } from "@/components/admin/AdminLayout";
import { PageMeta } from "@/components/PageMeta";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from "@/components/ui/alert-dialog";
import { Badge } from "@/components/ui/badge";
import { toast } from "@/hooks/use-toast";
import { format } from "date-fns";
import { CheckCircle, XCircle, Eye, Loader2 } from "lucide-react";
import { VERTICALS } from "@/lib/constants";

interface Application {
  id: string;
  user_id: string;
  buyer_id: string | null;
  company_description: string | null;
  website: string | null;
  license_number: string | null;
  years_in_business: number | null;
  logo_url: string | null;
  created_at: string | null;
}

export default function ProviderApplications() {
  const queryClient = useQueryClient();
  const [selectedApp, setSelectedApp] = useState<Application | null>(null);
  const [rejectTarget, setRejectTarget] = useState<Application | null>(null);
  const [approveForm, setApproveForm] = useState({
    business_name: "",
    contact_name: "",
    email: "",
    phone: "",
    vertical: "plumbing",
    service_areas: "",
  });

  const { data: applications, isLoading } = useQuery({
    queryKey: ["provider-applications"],
    queryFn: async () => {
      const { data, error } = await supabase
        .from("buyer_profiles")
        .select("*")
        .is("buyer_id", null)
        .order("created_at", { ascending: false });
      if (error) throw error;
      return data as Application[];
    },
  });

  const approveMutation = useMutation({
    mutationFn: async (app: Application) => {
      // Create the buyer record
      const { data: buyer, error: buyerError } = await supabase
        .from("buyers")
        .insert({
          business_name: approveForm.business_name,
          contact_name: approveForm.contact_name,
          email: approveForm.email,
          phone: approveForm.phone,
          vertical: approveForm.vertical,
          service_areas: approveForm.service_areas.split(",").map(s => s.trim()).filter(Boolean),
          is_active: true,
        })
        .select()
        .single();
      if (buyerError) throw buyerError;

      // Link the buyer_profile to the new buyer
      const { error: linkError } = await supabase
        .from("buyer_profiles")
        .update({ buyer_id: buyer.id })
        .eq("id", app.id);
      if (linkError) throw linkError;

      return buyer;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["provider-applications"] });
      queryClient.invalidateQueries({ queryKey: ["buyers"] });
      queryClient.invalidateQueries({ queryKey: ["admin-buyer-profiles"] });
      toast({ title: "Provider approved", description: "Buyer record created and profile linked." });
      setSelectedApp(null);
    },
    onError: (error: any) => {
      toast({ title: "Error", description: error.message, variant: "destructive" });
    },
  });

  const rejectMutation = useMutation({
    mutationFn: async (app: Application) => {
      const { error } = await supabase
        .from("buyer_profiles")
        .delete()
        .eq("id", app.id);
      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["provider-applications"] });
      queryClient.invalidateQueries({ queryKey: ["admin-buyer-profiles"] });
      toast({ title: "Application rejected", description: "Profile has been removed." });
      setRejectTarget(null);
    },
    onError: (error: any) => {
      toast({ title: "Error", description: error.message, variant: "destructive" });
    },
  });

  function openApprove(app: Application) {
    setApproveForm({
      business_name: "",
      contact_name: "",
      email: "",
      phone: "",
      vertical: "plumbing",
      service_areas: "",
    });
    setSelectedApp(app);
  }

  return (
    <>
      <PageMeta title="Provider Applications | Admin" description="Review and approve provider applications." />
      <AdminLayout>
        <div className="space-y-6">
          <div className="flex items-center justify-between">
            <h1 className="text-2xl font-bold font-sans">Provider Applications</h1>
            <Badge variant="secondary">{applications?.length ?? 0} pending</Badge>
          </div>

          {isLoading ? (
            <div className="flex justify-center py-20"><Loader2 className="h-8 w-8 animate-spin text-muted-foreground" /></div>
          ) : !applications || applications.length === 0 ? (
            <div className="rounded-lg border bg-card p-10 text-center text-muted-foreground">
              No pending applications.
            </div>
          ) : (
            <div className="rounded-lg border bg-card">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Description</TableHead>
                    <TableHead>Website</TableHead>
                    <TableHead>License</TableHead>
                    <TableHead>Years</TableHead>
                    <TableHead>Applied</TableHead>
                    <TableHead className="w-[140px]">Actions</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {applications.map((app) => (
                    <TableRow key={app.id}>
                      <TableCell className="max-w-[200px] truncate">{app.company_description || "—"}</TableCell>
                      <TableCell className="text-sm">{app.website || "—"}</TableCell>
                      <TableCell className="text-sm">{app.license_number || "—"}</TableCell>
                      <TableCell>{app.years_in_business ?? "—"}</TableCell>
                      <TableCell className="text-sm text-muted-foreground">
                        {app.created_at ? format(new Date(app.created_at), "MMM d, yyyy") : "—"}
                      </TableCell>
                      <TableCell>
                        <div className="flex gap-1">
                          <Button variant="ghost" size="icon" title="Review & Approve" onClick={() => openApprove(app)}>
                            <CheckCircle className="h-4 w-4 text-primary" />
                          </Button>
                          <Button variant="ghost" size="icon" title="Reject" onClick={() => setRejectTarget(app)}>
                            <XCircle className="h-4 w-4 text-destructive" />
                          </Button>
                        </div>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </div>
          )}
        </div>

        {/* Approve dialog */}
        <Dialog open={!!selectedApp} onOpenChange={(open) => { if (!open) setSelectedApp(null); }}>
          <DialogContent className="max-w-md">
            <DialogHeader>
              <DialogTitle>Approve Provider Application</DialogTitle>
            </DialogHeader>
            {selectedApp && (
              <div className="space-y-4">
                {selectedApp.company_description && (
                  <div className="rounded bg-muted p-3 text-sm">
                    <p className="font-medium text-xs text-muted-foreground mb-1">Applicant's Description</p>
                    {selectedApp.company_description}
                  </div>
                )}
                {selectedApp.website && (
                  <p className="text-sm">Website: <a href={selectedApp.website} target="_blank" rel="noopener noreferrer" className="text-primary hover:underline">{selectedApp.website}</a></p>
                )}

                <p className="text-sm font-medium text-muted-foreground">Fill in buyer details to create the account:</p>

                <div><Label>Business Name *</Label><Input value={approveForm.business_name} onChange={(e) => setApproveForm({ ...approveForm, business_name: e.target.value })} /></div>
                <div><Label>Contact Name *</Label><Input value={approveForm.contact_name} onChange={(e) => setApproveForm({ ...approveForm, contact_name: e.target.value })} /></div>
                <div><Label>Email *</Label><Input type="email" value={approveForm.email} onChange={(e) => setApproveForm({ ...approveForm, email: e.target.value })} /></div>
                <div><Label>Phone *</Label><Input value={approveForm.phone} onChange={(e) => setApproveForm({ ...approveForm, phone: e.target.value })} /></div>
                <div>
                  <Label>Vertical</Label>
                  <Select value={approveForm.vertical} onValueChange={(v) => setApproveForm({ ...approveForm, vertical: v })}>
                    <SelectTrigger><SelectValue /></SelectTrigger>
                    <SelectContent>
                      {Object.entries(VERTICALS).map(([key, v]) => <SelectItem key={key} value={key}>{v.label}</SelectItem>)}
                    </SelectContent>
                  </Select>
                </div>
                <div><Label>Service Areas (comma-separated)</Label><Input value={approveForm.service_areas} onChange={(e) => setApproveForm({ ...approveForm, service_areas: e.target.value })} placeholder="Santa Clarita, Valencia" /></div>

                <Button
                  onClick={() => approveMutation.mutate(selectedApp)}
                  disabled={!approveForm.business_name || !approveForm.email || !approveForm.phone || !approveForm.contact_name || approveMutation.isPending}
                  className="w-full"
                >
                  {approveMutation.isPending ? "Creating…" : "Approve & Create Buyer"}
                </Button>
              </div>
            )}
          </DialogContent>
        </Dialog>

        {/* Reject confirmation */}
        <AlertDialog open={!!rejectTarget} onOpenChange={(open) => { if (!open) setRejectTarget(null); }}>
          <AlertDialogContent>
            <AlertDialogHeader>
              <AlertDialogTitle>Reject this application?</AlertDialogTitle>
              <AlertDialogDescription>
                This will permanently remove the provider profile. This cannot be undone.
              </AlertDialogDescription>
            </AlertDialogHeader>
            <AlertDialogFooter>
              <AlertDialogCancel>Cancel</AlertDialogCancel>
              <AlertDialogAction onClick={() => rejectTarget && rejectMutation.mutate(rejectTarget)}>Reject</AlertDialogAction>
            </AlertDialogFooter>
          </AlertDialogContent>
        </AlertDialog>
      </AdminLayout>
    </>
  );
}

import { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { supabase } from "@/integrations/supabase/client";
import { PageMeta } from "@/components/PageMeta";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { toast } from "@/hooks/use-toast";
import { Wrench, Loader2 } from "lucide-react";

export default function ResetPassword() {
  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [loading, setLoading] = useState(false);
  const [ready, setReady] = useState(false);
  const navigate = useNavigate();

  useEffect(() => {
    // Listen for the PASSWORD_RECOVERY event which fires when user clicks the reset link
    const { data: { subscription } } = supabase.auth.onAuthStateChange((event) => {
      if (event === "PASSWORD_RECOVERY") {
        setReady(true);
      }
    });

    // Also check if we already have a session (user may have already been logged in via the recovery link)
    supabase.auth.getSession().then(({ data: { session } }) => {
      if (session) setReady(true);
    });

    return () => subscription.unsubscribe();
  }, []);

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    if (password !== confirmPassword) {
      toast({ title: "Passwords don't match", variant: "destructive" });
      return;
    }
    if (password.length < 6) {
      toast({ title: "Password must be at least 6 characters", variant: "destructive" });
      return;
    }
    setLoading(true);
    try {
      const { error } = await supabase.auth.updateUser({ password });
      if (error) throw error;
      toast({ title: "Password updated", description: "You can now sign in with your new password." });
      navigate("/admin");
    } catch (error: any) {
      toast({ title: "Failed to update password", description: error.message, variant: "destructive" });
    } finally {
      setLoading(false);
    }
  }

  return (
    <>
      <PageMeta title="Reset Password | HomeQuoteLink" description="Set a new password for your admin account." />
      <div className="flex min-h-screen items-center justify-center bg-muted p-4">
        <div className="w-full max-w-sm rounded-xl border bg-card p-8 shadow-lg">
          <div className="mb-6 flex items-center justify-center gap-2">
            <Wrench className="h-6 w-6 text-accent" />
            <span className="text-xl font-bold text-primary font-serif">HomeQuoteLink</span>
          </div>
          <h1 className="mb-6 text-center text-2xl font-bold font-sans">Set New Password</h1>
          {!ready ? (
            <p className="text-center text-muted-foreground text-sm">
              Loading your session… If this persists, try clicking the reset link from your email again.
            </p>
          ) : (
            <form onSubmit={handleSubmit} className="space-y-4">
              <div>
                <Label htmlFor="password">New Password</Label>
                <Input id="password" type="password" value={password} onChange={(e) => setPassword(e.target.value)} required />
              </div>
              <div>
                <Label htmlFor="confirmPassword">Confirm Password</Label>
                <Input id="confirmPassword" type="password" value={confirmPassword} onChange={(e) => setConfirmPassword(e.target.value)} required />
              </div>
              <Button type="submit" className="w-full" disabled={loading}>
                {loading ? <><Loader2 className="h-4 w-4 animate-spin" /> Updating…</> : "Update Password"}
              </Button>
            </form>
          )}
        </div>
      </div>
    </>
  );
}

import { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { AdminLayout } from "@/components/admin/AdminLayout";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle, AlertDialogTrigger } from "@/components/ui/alert-dialog";
import { toast } from "@/hooks/use-toast";
import { format } from "date-fns";
import { CheckCircle, Trash2, XCircle } from "lucide-react";

export default function Reviews() {
  const [ratingFilter, setRatingFilter] = useState<string>("all");
  const queryClient = useQueryClient();

  const { data: reviews, isLoading } = useQuery({
    queryKey: ["admin-reviews"],
    queryFn: async () => {
      const { data, error } = await supabase
        .from("reviews")
        .select("*, buyers(business_name)")
        .order("created_at", { ascending: false });
      if (error) throw error;
      return data;
    },
  });

  const { data: homeowners } = useQuery({
    queryKey: ["admin-homeowners-map"],
    queryFn: async () => {
      const { data, error } = await supabase.from("homeowner_profiles").select("user_id, full_name, email");
      if (error) throw error;
      return new Map(data.map((h) => [h.user_id, h]));
    },
  });

  const toggleVerified = useMutation({
    mutationFn: async ({ id, verified }: { id: string; verified: boolean }) => {
      const { error } = await supabase.from("reviews").update({ is_verified: verified }).eq("id", id);
      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["admin-reviews"] });
      toast({ title: "Review updated" });
    },
  });

  const deleteReview = useMutation({
    mutationFn: async (id: string) => {
      const { error } = await supabase.from("reviews").delete().eq("id", id);
      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["admin-reviews"] });
      toast({ title: "Review deleted" });
    },
  });

  const filtered = reviews?.filter((r) => {
    if (ratingFilter !== "all" && r.rating !== parseInt(ratingFilter)) return false;
    return true;
  });

  return (
    <AdminLayout>
      <div className="space-y-6">
        <div className="flex items-center justify-between">
          <h1 className="text-2xl font-bold text-foreground">Reviews</h1>
          <Badge variant="secondary">{reviews?.length ?? 0} total</Badge>
        </div>

        <div className="flex gap-2">
          <Select value={ratingFilter} onValueChange={setRatingFilter}>
            <SelectTrigger className="w-40">
              <SelectValue placeholder="Filter by rating" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All ratings</SelectItem>
              {[5, 4, 3, 2, 1].map((r) => (
                <SelectItem key={r} value={String(r)}>{r} star{r > 1 ? "s" : ""}</SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>

        <div className="rounded-md border">
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Reviewer</TableHead>
                <TableHead>Provider</TableHead>
                <TableHead>Rating</TableHead>
                <TableHead>Review</TableHead>
                <TableHead>Response</TableHead>
                <TableHead>Verified</TableHead>
                <TableHead>Date</TableHead>
                <TableHead className="w-24">Actions</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {isLoading ? (
                <TableRow><TableCell colSpan={8} className="text-center text-muted-foreground">Loading…</TableCell></TableRow>
              ) : filtered?.length === 0 ? (
                <TableRow><TableCell colSpan={8} className="text-center text-muted-foreground">No reviews</TableCell></TableRow>
              ) : (
                filtered?.map((r: any) => {
                  const reviewer = homeowners?.get(r.reviewer_user_id);
                  return (
                    <TableRow key={r.id}>
                      <TableCell className="font-medium">{reviewer?.full_name || reviewer?.email || r.reviewer_user_id.slice(0, 8)}</TableCell>
                      <TableCell>{r.buyers?.business_name || "—"}</TableCell>
                      <TableCell>{"★".repeat(r.rating)}{"☆".repeat(5 - r.rating)}</TableCell>
